import org.apache.kafka.common.serialization.StringDeserializer;
import org.apache.kafka.common.serialization.StringSerializer;

import java.time.Duration;
import java.util.Collections;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;

/**
 * This example demonstrates how to use the Apicurio Registry in a very simple publish/subscribe scenario
 * where applications use a mix of Confluent and Apicurio Registry serdes classes. This example uses the
 * Confluent serializer for the producer and the Apicurio Registry deserializer class for the consumer.
 * <ol>
 * <li>Configuring a Confluent Kafka Serializer for use with Apicurio Registry</li>
 * <li>Configuring a Kafka Deserializer for use with Apicurio Registry</li>
 * <li>Auto-register the Avro schema in the registry (registered by the producer)</li>
 * <li>Data sent as a simple GenericRecord, no java beans needed</li>
 * </ol>
 * Pre-requisites:
 * <ul>
 * <li>Kafka must be running on localhost:9092</li>
 * <li>Apicurio Registry must be running on localhost:8080</li>
 * </ul>
 *
 * @author eric.wittmann@gmail.com
 */
public class ConfluentSerdesExample {

    private static final String REGISTRY_URL = "http://localhost:8080/apis/registry/v3";
    private static final String CCOMPAT_API_URL = "http://localhost:8080/apis/ccompat/v7";

    private static final String SERVERS = "localhost:9092";
    private static final String TOPIC_NAME = ConfluentSerdesExample.class.getSimpleName();
    private static final String SUBJECT_NAME = "Greeting";
    private static final String SCHEMA = "{\"type\":\"record\",\"name\":\"Greeting\",\"fields\":[{\"name\":\"Message\",\"type\":\"string\"},{\"name\":\"Timestamp\",\"type\":\"long\"}]}";

    public static final void main(String[] args) throws Exception {
        System.out.println("Starting example " + ConfluentSerdesExample.class.getSimpleName());
        String topicName = TOPIC_NAME;
        String subjectName = SUBJECT_NAME;

        // Create the producer.
        Producer<String, Object> producer = createKafkaProducer();
        // Produce 5 messages.
        int producedMessages = 0;
        try {
            Schema schema = new Schema.Parser().parse(SCHEMA);
            System.out.println("Producing (5) messages.");
            for (int idx = 0; idx < 5; idx++) {
                // Use the schema to create a record
                GenericRecord record = new GenericData.Record(schema);
                Date now = new Date();
                String message = "Hello (" + producedMessages++ + ")!";
                record.put("Message", message);
                record.put("Timestamp", now.getTime());

                // Send/produce the message on the Kafka Producer
                ProducerRecord<String, Object> producedRecord = new ProducerRecord<>(topicName, subjectName,
                        record);
                producer.send(producedRecord);

                Thread.sleep(100);
            }
            System.out.println("Messages successfully produced.");
        } finally {
            System.out.println("Closing the producer.");
            producer.flush();
            producer.close();
        }

        // Create the consumer
        System.out.println("Creating the consumer.");
        KafkaConsumer<Long, GenericRecord> consumer = createKafkaConsumer();

        // Subscribe to the topic
        System.out.println("Subscribing to topic " + topicName);
        consumer.subscribe(Collections.singletonList(topicName));

        // Consume the 5 messages.
        try {
            int messageCount = 0;
            System.out.println("Consuming (5) messages.");
            while (messageCount < 5) {
                final ConsumerRecords<Long, GenericRecord> records = consumer.poll(Duration.ofSeconds(1));
                messageCount += records.count();
                if (records.count() == 0) {
                    // Do nothing - no messages waiting.
                    System.out.println("No messages waiting...");
                } else
                    records.forEach(record -> {
                        GenericRecord value = record.value();
                        System.out.println("Consumed a message: " + value.get("Message") + " @ "
                                + new Date((long) value.get("Timestamp")));
                    });
            }
        } finally {
            consumer.close();
        }

        System.out.println("Done (success).");
    }

    /**
     * Creates the Kafka producer.
     */
    private static Producer<String, Object> createKafkaProducer() {
        Properties props = new Properties();

        // Configure kafka settings
        props.putIfAbsent(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, SERVERS);
        props.putIfAbsent(ProducerConfig.CLIENT_ID_CONFIG, "Producer-" + TOPIC_NAME);
        props.putIfAbsent(ProducerConfig.ACKS_CONFIG, "all");
        props.putIfAbsent(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());

        configureSecurityIfPresent(props);

        RestService restService = new RestService(CCOMPAT_API_URL);
        final Map<String, String> restServiceProperties = new HashMap<>();
        // If auth is enabled using the env var, we try to configure it
        if (Boolean.parseBoolean(System.getenv("CONFIGURE_AUTH"))) {
            restServiceProperties.put("basic.auth.credentials.source", "USER_INFO");
            restServiceProperties.put("schema.registry.basic.auth.user.info",
                    String.format("%s:%s", System.getenv(SerdeConfig.AUTH_CLIENT_ID),
                            System.getenv(SerdeConfig.AUTH_CLIENT_SECRET)));
        }

        CachedSchemaRegistryClient schemaRegistryClient = new CachedSchemaRegistryClient(restService, 100,
                restServiceProperties);

        Map<String, String> properties = new HashMap<>();

        // Configure Service Registry location (Confluent API)
        properties.put("schema.registry.url", CCOMPAT_API_URL);
        properties.put("auto.register.schemas", "true");
        // Map the topic name to the artifactId in the registry
        properties.put("value.subject.name.strategy",
                "io.confluent.kafka.serializers.subject.TopicRecordNameStrategy");

        // Use the Confluent provided Kafka Serializer for Avro
        KafkaAvroSerializer valueSerializer = new KafkaAvroSerializer(schemaRegistryClient, properties);
        StringSerializer keySerializer = new StringSerializer();

        // Create the Kafka producer
        Producer<String, Object> producer = new KafkaProducer<String, Object>(props, keySerializer,
                valueSerializer);
        return producer;
    }

    /**
     * Creates the Kafka consumer.
     */
    private static KafkaConsumer<Long, GenericRecord> createKafkaConsumer() {
        Properties props = new Properties();

        // Configure Kafka
        props.putIfAbsent(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, SERVERS);
        props.putIfAbsent(ConsumerConfig.GROUP_ID_CONFIG, "Consumer-" + TOPIC_NAME);
        props.putIfAbsent(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "true");
        props.putIfAbsent(ConsumerConfig.AUTO_COMMIT_INTERVAL_MS_CONFIG, "1000");
        props.putIfAbsent(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
        props.putIfAbsent(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        // Use the Apicurio Registry provided Kafka Deserializer for Avro
        props.putIfAbsent(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,
                AvroKafkaDeserializer.class.getName());

        // Configure Service Registry location
        props.putIfAbsent(SerdeConfig.REGISTRY_URL, REGISTRY_URL);
        // No other configuration needed for the deserializer, because the contentId of the schema
        // the deserializer should use is sent as part of the payload. So the deserializer simply
        // extracts that globalId and uses it to look up the Schema from the registry.

        // Just if security values are present, then we configure them.
        configureSecurityIfPresent(props);

        // Create the Kafka Consumer
        KafkaConsumer<Long, GenericRecord> consumer = new KafkaConsumer<>(props);
        return consumer;
    }

    private static void configureSecurityIfPresent(Properties props) {
        final String tokenEndpoint = System.getenv(SerdeConfig.AUTH_TOKEN_ENDPOINT);
        if (tokenEndpoint != null) {

            final String authClient = System.getenv(SerdeConfig.AUTH_CLIENT_ID);
            final String authSecret = System.getenv(SerdeConfig.AUTH_CLIENT_SECRET);

            props.putIfAbsent(SerdeConfig.AUTH_CLIENT_SECRET, authSecret);
            props.putIfAbsent(SerdeConfig.AUTH_CLIENT_ID, authClient);
            props.putIfAbsent(SerdeConfig.AUTH_TOKEN_ENDPOINT, tokenEndpoint);
            props.putIfAbsent(SaslConfigs.SASL_MECHANISM, "OAUTHBEARER");
            props.putIfAbsent(SaslConfigs.SASL_LOGIN_CALLBACK_HANDLER_CLASS,
                    "io.strimzi.kafka.oauth.client.JaasClientOauthLoginCallbackHandler");
            props.putIfAbsent("security.protocol", "SASL_SSL");

            props.putIfAbsent(SaslConfigs.SASL_JAAS_CONFIG,
                    String.format(
                            "org.apache.kafka.common.security.oauthbearer.OAuthBearerLoginModule required "
                                    + "  oauth.client.id=\"%s\" " + "  oauth.client.secret=\"%s\" "
                                    + "  oauth.token.endpoint.uri=\"%s\" ;",
                            authClient, authSecret, tokenEndpoint));
        }
    }

}

package io.apicurio.registry.examples.customtypes;

import io.apicurio.registry.content.TypedContent;

import java.util.LinkedHashSet;
import java.util.Set;

/**
 * Tiny Markdown "model" shared by the MARKDOWN artifact type providers: a document has a title
 * (the first level-1 heading) and a set of sections (level-2 headings).
 */
final class Markdown {

    static final String CONTENT_TYPE = "text/markdown";

    private Markdown() {
    }

    static String text(TypedContent content) {
        return content.getContent().content();
    }

    /** Returns the text of the first {@code # } heading, or {@code null} when there is none. */
    static String title(String markdown) {
        for (String line : markdown.split("\n")) {
            String trimmed = line.trim();
            if (trimmed.isEmpty()) {
                continue;
            }
            return trimmed.startsWith("# ") ? trimmed.substring(2).trim() : null;
        }
        return null;
    }

    /** Returns the texts of all {@code ## } headings, in document order. */
    static Set<String> sections(String markdown) {
        Set<String> sections = new LinkedHashSet<>();
        for (String line : markdown.split("\n")) {
            String trimmed = line.trim();
            if (trimmed.startsWith("## ")) {
                sections.add(trimmed.substring(3).trim());
            }
        }
        return sections;
    }

    /** Normalizes line endings and trailing whitespace so that equivalent documents hash alike. */
    static String canonicalize(String markdown) {
        StringBuilder out = new StringBuilder(markdown.length());
        for (String line : markdown.replace("\r\n", "\n").replace('\r', '\n').split("\n", -1)) {
            out.append(line.stripTrailing()).append('\n');
        }
        return out.toString().strip() + "\n";
    }
}

package io.apicurio.registry.examples.customtypes;

import io.apicurio.registry.content.TypedContent;
import io.apicurio.registry.rules.compatibility.CompatibilityChecker;
import io.apicurio.registry.rules.compatibility.CompatibilityExecutionResult;
import io.apicurio.registry.rules.compatibility.CompatibilityLevel;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Backs the COMPATIBILITY rule for the MARKDOWN artifact type. A new version is:
 * <ul>
 * <li>{@code BACKWARD} compatible when it keeps the title and all sections of the previous version
 * (sections may be added);</li>
 * <li>{@code FORWARD} compatible when it does not introduce new sections;</li>
 * <li>{@code FULL} compatible when both hold.</li>
 * </ul>
 * The {@code *_TRANSITIVE} levels apply the same checks against every existing version.
 */
public class MarkdownCompatibilityChecker implements CompatibilityChecker {

    @Override
    public CompatibilityExecutionResult testCompatibility(CompatibilityLevel level,
            List<TypedContent> existingArtifacts, TypedContent proposedArtifact,
            Map<String, TypedContent> resolvedReferences) {
        if (level == null || level == CompatibilityLevel.NONE || existingArtifacts == null
                || existingArtifacts.isEmpty()) {
            return CompatibilityExecutionResult.compatible();
        }
        boolean transitive = level.name().endsWith("_TRANSITIVE");
        boolean backward = level.name().startsWith("BACKWARD") || level.name().startsWith("FULL");
        boolean forward = level.name().startsWith("FORWARD") || level.name().startsWith("FULL");

        List<TypedContent> toCompare = transitive ? existingArtifacts
            : List.of(existingArtifacts.get(existingArtifacts.size() - 1));
        String proposed = Markdown.text(proposedArtifact);
        String proposedTitle = Markdown.title(proposed);
        Set<String> proposedSections = Markdown.sections(proposed);

        List<String> problems = new ArrayList<>();
        for (TypedContent existingContent : toCompare) {
            String existing = Markdown.text(existingContent);
            if (!Objects.equals(Markdown.title(existing), proposedTitle)) {
                problems.add("Title changed from \"" + Markdown.title(existing) + "\" to \"" + proposedTitle + "\".");
            }
            Set<String> existingSections = Markdown.sections(existing);
            if (backward) {
                for (String section : existingSections) {
                    if (!proposedSections.contains(section)) {
                        problems.add("Section \"" + section + "\" was removed.");
                    }
                }
            }
            if (forward) {
                for (String section : proposedSections) {
                    if (!existingSections.contains(section)) {
                        problems.add("Section \"" + section + "\" was added.");
                    }
                }
            }
        }
        return problems.isEmpty() ? CompatibilityExecutionResult.compatible()
            : CompatibilityExecutionResult.incompatible(String.join(" ", problems));
    }
}

package io.apicurio.registry.examples.customtypes;

import io.apicurio.registry.content.ContentAccepter;
import io.apicurio.registry.content.TypedContent;

import java.util.Map;

/**
 * Lets the registry auto-detect the MARKDOWN artifact type when a client does not specify one:
 * the content type is {@code text/markdown}, or the document starts with a level-1 heading.
 */
public class MarkdownContentAccepter implements ContentAccepter {

    @Override
    public boolean acceptsContent(TypedContent content, Map<String, TypedContent> resolvedReferences) {
        if (Markdown.CONTENT_TYPE.equalsIgnoreCase(content.getContentType())) {
            return true;
        }
        return Markdown.title(Markdown.text(content)) != null;
    }
}

package io.apicurio.registry.examples.customtypes;

import io.apicurio.registry.content.ContentHandle;
import io.apicurio.registry.content.TypedContent;
import io.apicurio.registry.content.canon.ContentCanonicalizer;

import java.util.Map;

/**
 * Canonical form of a MARKDOWN document: LF line endings, no trailing whitespace, single trailing
 * newline. The registry uses it to recognise equivalent content (for example when searching with
 * {@code canonical=true}).
 */
public class MarkdownContentCanonicalizer implements ContentCanonicalizer {

    @Override
    public TypedContent canonicalize(TypedContent content, Map<String, TypedContent> resolvedReferences) {
        String canonical = Markdown.canonicalize(Markdown.text(content));
        return TypedContent.create(ContentHandle.create(canonical), Markdown.CONTENT_TYPE);
    }
}

