/**
 * This example application showcases a scenario where Apache Avro messages are published to the same Kafka
 * topic using different Avro schemas. This example uses the Apicurio Registry serdes classes to serialize and
 * deserialize Apache Avro messages using different schemas, even if received in the same Kafka topic. The
 * following aspects are demonstrated:
 * <ol>
 * <li>Configuring a Kafka Serializer for use with Apicurio Registry</li>
 * <li>Configuring a Kafka Deserializer for use with Apicurio Registry</li>
 * <li>Auto-register the Avro schema in the registry (registered by the producer)</li>
 * <li>Data sent as a simple GenericRecord, no java beans needed</li>
 * <li>Producing and consuming Avro messages using different schemas mapped to different Apicurio Registry
 * Artifacts</li>
 * </ol>
 * <p>
 * Pre-requisites:
 * <ul>
 * <li>Kafka must be running on localhost:9092</li>
 * <li>Apicurio Registry must be running on localhost:8080</li>
 * </ul>
 *
 * @author Fabian Martinez
 * @author Carles Arnal
 */
public class MixAvroExample {

    private static final String REGISTRY_URL = "http://localhost:8080/apis/registry/v3";
    private static final String SERVERS = "localhost:9092";
    private static final String TOPIC_NAME = MixAvroExample.class.getSimpleName();
    private static final String SCHEMAV1 = "{\"type\":\"record\",\"name\":\"Greeting\",\"fields\":[{\"name\":\"Message\",\"type\":\"string\"},{\"name\":\"Time\",\"type\":\"long\"}]}";
    private static final String SCHEMAV2 = "{\"type\":\"record\",\"name\":\"Greeting\",\"fields\":[{\"name\":\"Message\",\"type\":\"string\"},{\"name\":\"Time\",\"type\":\"long\"},{\"name\":\"Extra\",\"type\":\"string\"}]}";
    private static final String FAREWELLSCHEMAV1 = "{\"type\":\"record\",\"name\":\"Farewell\",\"fields\":[{\"name\":\"Message\",\"type\":\"string\"},{\"name\":\"Time\",\"type\":\"long\"}]}";
    private static final String FAREWELLSCHEMAV2 = "{\"type\":\"record\",\"name\":\"Farewell\",\"fields\":[{\"name\":\"Message\",\"type\":\"string\"},{\"name\":\"Time\",\"type\":\"long\"},{\"name\":\"Extra\",\"type\":\"string\"}]}";

    public static void main(String[] args) throws Exception {
        System.out.println("Starting example " + MixAvroExample.class.getSimpleName());
        String topicName = TOPIC_NAME;

        // Create the producer.
        Producer<Object, Object> producer = createKafkaProducer();

        int producedMessages = 0;
        try {
            producedMessages += produceMessages(producer, topicName, SCHEMAV1, null);

            producedMessages += produceMessages(producer, topicName, SCHEMAV2, "extra greeting");

            producedMessages += produceMessages(producer, topicName, FAREWELLSCHEMAV1, null);

            producedMessages += produceMessages(producer, topicName, FAREWELLSCHEMAV2, "extra farewell");

        } finally {
            System.out.println("Closing the producer.");
            producer.flush();
            producer.close();
        }

        // Create the consumer
        System.out.println("Creating the consumer.");
        KafkaConsumer<Long, GenericRecord> consumer = createKafkaConsumer();

        // Subscribe to the topic

        // Consume the 5 messages.
        try (consumer) {
            System.out.println("Subscribing to topic " + topicName);
            consumer.subscribe(Collections.singletonList(topicName));
            int messageCount = 0;
            System.out.println("Consuming (" + producedMessages + ") messages.");
            while (messageCount < producedMessages) {
                final ConsumerRecords<Long, GenericRecord> records = consumer.poll(Duration.ofSeconds(1));
                messageCount += records.count();
                if (records.count() == 0) {
                    // Do nothing - no messages waiting.
                    System.out.println("No messages waiting...");
                } else
                    records.forEach(record -> {
                        GenericRecord value = record.value();
                        value.getSchema().getFullName();
                        if (value.hasField("Extra")) {
                            System.out.println("Consumed " + value.getSchema().getFullName() + ": "
                                    + value.get("Message") + " @ " + new Date((long) value.get("Time"))
                                    + " @ " + value.get("Extra"));
                        } else {
                            System.out.println("Consumed " + value.getSchema().getFullName() + ": "
                                    + value.get("Message") + " @ " + new Date((long) value.get("Time")));
                        }
                    });
            }
        }

        System.out.println("Done (success).");
    }

    private static int produceMessages(Producer<Object, Object> producer, String topicName,
            String schemaContent, String extra) throws InterruptedException {
        int producedMessages = 0;
        Schema schema = new Schema.Parser().parse(schemaContent);
        System.out.println("Producing (5) messages.");
        for (int idx = 0; idx < 5; idx++) {
            // Use the schema to create a record
            GenericRecord record = new GenericData.Record(schema);
            Date now = new Date();
            String message = "Hello (" + producedMessages++ + ")!";
            record.put("Message", message);
            record.put("Time", now.getTime());
            if (extra != null) {
                record.put("Extra", extra);
            }

            // Send/produce the message on the Kafka Producer
            ProducerRecord<Object, Object> producedRecord = new ProducerRecord<>(topicName,
                    UUID.randomUUID().toString(), record);
            producer.send(producedRecord);

            Thread.sleep(100);
        }
        System.out.println("Messages successfully produced.");
        return producedMessages;
    }

    /**
     * Creates the Kafka producer.
     */
    private static Producer<Object, Object> createKafkaProducer() {
        Properties props = new Properties();

        // Configure kafka settings
        props.putIfAbsent(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, SERVERS);
        props.putIfAbsent(ProducerConfig.CLIENT_ID_CONFIG, "Producer-" + TOPIC_NAME);
        props.putIfAbsent(ProducerConfig.ACKS_CONFIG, "all");
        props.putIfAbsent(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        // Use the Apicurio Registry provided Kafka Serializer for Avro
        props.putIfAbsent(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, AvroKafkaSerializer.class.getName());

        // Configure Service Registry location
        props.putIfAbsent(SerdeConfig.REGISTRY_URL, REGISTRY_URL);
        props.putIfAbsent(SerdeConfig.EXPLICIT_ARTIFACT_GROUP_ID, MixAvroExample.class.getSimpleName());
        // Map the topic name to the artifactId in the registry
        props.putIfAbsent(SerdeConfig.ARTIFACT_RESOLVER_STRATEGY, RecordIdStrategy.class.getName());
        // Get an existing schema or auto-register if not found
        props.putIfAbsent(SerdeConfig.AUTO_REGISTER_ARTIFACT, Boolean.TRUE);

        // Just if security values are present, then we configure them.
        configureSecurityIfPresent(props);

        // Create the Kafka producer
        Producer<Object, Object> producer = new KafkaProducer<>(props);
        return producer;
    }

    /**
     * Creates the Kafka consumer.
     */
    private static KafkaConsumer<Long, GenericRecord> createKafkaConsumer() {
        Properties props = new Properties();

        // Configure Kafka
        props.putIfAbsent(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, SERVERS);
        props.putIfAbsent(ConsumerConfig.GROUP_ID_CONFIG, "Consumer-" + TOPIC_NAME);
        props.putIfAbsent(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "true");
        props.putIfAbsent(ConsumerConfig.AUTO_COMMIT_INTERVAL_MS_CONFIG, "1000");
        props.putIfAbsent(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
        props.putIfAbsent(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        // Use the Apicurio Registry provided Kafka Deserializer for Avro
        props.putIfAbsent(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,
                AvroKafkaDeserializer.class.getName());

        // Configure Service Registry location
        props.putIfAbsent(SerdeConfig.REGISTRY_URL, REGISTRY_URL);
        // No other configuration needed for the deserializer, because the globalId of the schema
        // the deserializer should use is sent as part of the payload. So the deserializer simply
        // extracts that globalId and uses it to look up the Schema from the registry.

        // Just if security values are present, then we configure them.
        configureSecurityIfPresent(props);

        // Create the Kafka Consumer
        KafkaConsumer<Long, GenericRecord> consumer = new KafkaConsumer<>(props);
        return consumer;
    }

    private static void configureSecurityIfPresent(Properties props) {
        final String tokenEndpoint = System.getenv(SerdeConfig.AUTH_TOKEN_ENDPOINT);
        if (tokenEndpoint != null) {

            final String authClient = System.getenv(SerdeConfig.AUTH_CLIENT_ID);
            final String authSecret = System.getenv(SerdeConfig.AUTH_CLIENT_SECRET);

            props.putIfAbsent(SerdeConfig.AUTH_CLIENT_SECRET, authSecret);
            props.putIfAbsent(SerdeConfig.AUTH_CLIENT_ID, authClient);
            props.putIfAbsent(SerdeConfig.AUTH_TOKEN_ENDPOINT, tokenEndpoint);
            props.putIfAbsent(SaslConfigs.SASL_MECHANISM, "OAUTHBEARER");
            props.putIfAbsent(SaslConfigs.SASL_LOGIN_CALLBACK_HANDLER_CLASS,
                    "io.strimzi.kafka.oauth.client.JaasClientOauthLoginCallbackHandler");
            props.putIfAbsent("security.protocol", "SASL_SSL");

            props.putIfAbsent(SaslConfigs.SASL_JAAS_CONFIG,
                    String.format(
                            "org.apache.kafka.common.security.oauthbearer.OAuthBearerLoginModule required "
                                    + "  oauth.client.id=\"%s\" " + "  oauth.client.secret=\"%s\" "
                                    + "  oauth.token.endpoint.uri=\"%s\" ;",
                            authClient, authSecret, tokenEndpoint));
        }
    }
}

package io.apicurio.registry.examples.mtls;

import io.apicurio.registry.client.common.DefaultVertxInstance;
import io.apicurio.registry.client.RegistryClientFactory;
import io.apicurio.registry.client.common.RegistryClientOptions;
import io.apicurio.registry.rest.client.RegistryClient;
import io.apicurio.registry.rest.client.models.CreateArtifact;
import io.apicurio.registry.rest.client.models.CreateArtifactResponse;
import io.apicurio.registry.rest.client.models.CreateVersion;
import io.apicurio.registry.rest.client.models.IfArtifactExists;
import io.apicurio.registry.rest.client.models.SystemInfo;
import io.apicurio.registry.rest.client.models.VersionContent;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.util.UUID;

/**
 * Example client demonstrating mutual TLS (mTLS) authentication with Apicurio Registry.
 *
 * This client:
 * 1. Connects to a registry requiring mutual TLS authentication
 * 2. Uses client certificates to authenticate
 * 3. Performs basic registry operations (create, read, delete artifacts)
 *
 */
public class MtlsClientDemo {

    private static final String SAMPLE_JSON_SCHEMA = "{\n" +
            "    \"$id\": \"https://example.com/person.schema.json\",\n" +
            "    \"$schema\": \"http://json-schema.org/draft-07/schema#\",\n" +
            "    \"title\": \"Person\",\n" +
            "    \"type\": \"object\",\n" +
            "    \"properties\": {\n" +
            "        \"firstName\": {\n" +
            "            \"type\": \"string\",\n" +
            "            \"description\": \"The person's first name.\"\n" +
            "        },\n" +
            "        \"lastName\": {\n" +
            "            \"type\": \"string\",\n" +
            "            \"description\": \"The person's last name.\"\n" +
            "        },\n" +
            "        \"age\": {\n" +
            "            \"type\": \"integer\",\n" +
            "            \"description\": \"Age in years.\",\n" +
            "            \"minimum\": 0\n" +
            "        }\n" +
            "    }\n" +
            "}";

    public static void main(String[] args) {
        System.out.println("========================================");
        System.out.println("Apicurio Registry mTLS Client Demo");
        System.out.println("========================================");
        System.out.println();

        // Configuration
        String registryUrl = getEnvOrDefault("REGISTRY_URL", "https://localhost:8443/apis/registry/v3");
        String certsDir = getEnvOrDefault("CERTS_DIR", "../certs");

        String clientKeystorePath = certsDir + "/client-keystore.p12";
        String clientTruststorePath = certsDir + "/client-truststore.p12";
        String keystorePassword = getEnvOrDefault("KEYSTORE_PASSWORD", "apicurio");

        System.out.println("Configuration:");
        System.out.println("  Registry URL: " + registryUrl);
        System.out.println("  Client Keystore: " + clientKeystorePath);
        System.out.println("  Client Truststore: " + clientTruststorePath);
        System.out.println();

        // Validate certificate files exist
        if (!new File(clientKeystorePath).exists()) {
            System.err.println("ERROR: Client keystore not found at: " + clientKeystorePath);
            System.err.println("Please generate certificates first using: ../certs/generate-certs.sh");
            System.exit(1);
        }

        try {
            // Create client with mTLS configuration
            System.out.println("1. Creating registry client with mTLS...");
            RegistryClient client = createMtlsClient(registryUrl, clientKeystorePath,
                    clientTruststorePath, keystorePassword);
            System.out.println("   Client created successfully");
            System.out.println();

            // Test connection by getting system info
            System.out.println("2. Testing connection - getting system info...");
            SystemInfo systemInfo = client.system().info().get();
            System.out.println("   Connected successfully!");
            System.out.println("   Registry Name: " + systemInfo.getName());
            System.out.println("   Version: " + systemInfo.getVersion());
            System.out.println("   Description: " + systemInfo.getDescription());
            System.out.println();

            // Create a new artifact
            String artifactId = "mtls-demo-" + UUID.randomUUID().toString();
            System.out.println("3. Creating artifact: " + artifactId);

            CreateArtifact createArtifact = new CreateArtifact();
            createArtifact.setArtifactType("JSON");
            createArtifact.setArtifactId(artifactId);
            createArtifact.setFirstVersion(new CreateVersion());
            createArtifact.getFirstVersion().setContent(new VersionContent());
            createArtifact.getFirstVersion().getContent().setContent(SAMPLE_JSON_SCHEMA);
            createArtifact.getFirstVersion().getContent().setContentType("application/json");

            CreateArtifactResponse response = client.groups().byGroupId("default")
                    .artifacts().post(createArtifact, config -> {
                        config.queryParameters.ifExists = IfArtifactExists.FAIL;
                    });

            System.out.println("   Artifact created successfully");
            System.out.println("   Group: " + response.getArtifact().getGroupId());
            System.out.println("   Artifact ID: " + response.getArtifact().getArtifactId());
            System.out.println("   Version: " + response.getVersion().getVersion());
            System.out.println("   Global ID: " + response.getVersion().getGlobalId());
            System.out.println();

            // Retrieve the artifact
            System.out.println("4. Retrieving artifact...");
            var contentStream = client.groups().byGroupId("default")
                    .artifacts().byArtifactId(artifactId)
                    .versions().byVersionExpression("branch=latest")
                    .content().get();

            String retrievedContent = new String(contentStream.readAllBytes(), StandardCharsets.UTF_8);
            System.out.println("   Artifact retrieved successfully");
            System.out.println("   Content length: " + retrievedContent.length() + " bytes");
            System.out.println();

            // Delete the artifact
            System.out.println("5. Deleting artifact...");
            client.groups().byGroupId("default")
                    .artifacts().byArtifactId(artifactId)
                    .delete();
            System.out.println("   Artifact deleted successfully");
            System.out.println();

            System.out.println("========================================");
            System.out.println("Demo completed successfully!");
            System.out.println("========================================");
            System.out.println();
            System.out.println("This demo has successfully demonstrated:");
            System.out.println("  - Mutual TLS authentication with client certificates");
            System.out.println("  - Secure connection to Apicurio Registry");
            System.out.println("  - Basic registry operations (create, read, delete)");

        } catch (Exception e) {
            System.err.println();
            System.err.println("========================================");
            System.err.println("ERROR: Demo failed");
            System.err.println("========================================");
            System.err.println();

            if (e.getMessage() != null && e.getMessage().toLowerCase().contains("certificate")) {
                System.err.println("This appears to be a certificate-related error.");
                System.err.println("Please ensure:");
                System.err.println("  1. Certificates were generated: ../certs/generate-certs.sh");
                System.err.println("  2. Registry is deployed with mTLS enabled");
                System.err.println("  3. Port forwarding is active: kubectl port-forward -n apicurio-mtls svc/apicurio-registry-mtls-app-service 8443:8443");
            }

            System.err.println();
            System.err.println("Error details: " + e.getMessage());
            if (e.getCause() != null) {
                System.err.println("Caused by: " + e.getCause().getMessage());
            }
            System.exit(1);
        } finally {
            // Clean up Vert.x instance
            DefaultVertxInstance.close();
        }
    }

    /**
     * Creates a registry client configured for mutual TLS authentication.
     */
    private static RegistryClient createMtlsClient(String registryUrl, String keystorePath,
            String truststorePath, String password) {

        RegistryClientOptions options = RegistryClientOptions.create(registryUrl)
                // Configure client keystore (for client authentication)
                .keystorePkcs12(keystorePath, password)
                // Configure truststore (to trust server certificate)
                .trustStorePkcs12(truststorePath, password);

        return RegistryClientFactory.create(options);
    }

    /**
     * Helper method to get environment variable or default value.
     */
    private static String getEnvOrDefault(String envVar, String defaultValue) {
        String value = System.getenv(envVar);
        return value != null ? value : defaultValue;
    }
}

