package io.apicurio.registry.examples.util;

import io.apicurio.registry.rest.client.RegistryClient;
import io.apicurio.registry.rest.client.models.ArtifactMetaData;
import io.apicurio.registry.rest.client.models.CreateArtifact;
import io.apicurio.registry.rest.client.models.CreateVersion;
import io.apicurio.registry.rest.client.models.IfArtifactExists;
import io.apicurio.registry.rest.client.models.VersionContent;
import io.apicurio.registry.utils.IoUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

public class RegistryDemoUtil {

    private static final Logger LOGGER = LoggerFactory.getLogger(RegistryDemoUtil.class);

    /**
     * Create the artifact in the registry (or update it if it already exists).
     *
     * @param artifactId
     * @param schema
     */
    public static void createSchemaInServiceRegistry(RegistryClient registryClient, String artifactId,
            String schema) {

        LOGGER.info("---------------------------------------------------------");
        LOGGER.info("=====> Creating artifact in the registry for JSON Schema with ID: {}", artifactId);
        try {
            final ByteArrayInputStream content = new ByteArrayInputStream(
                    schema.getBytes(StandardCharsets.UTF_8));

            CreateArtifact createArtifact = new CreateArtifact();
            createArtifact.setArtifactId(artifactId);
            createArtifact.setArtifactType("JSON");
            createArtifact.setFirstVersion(new CreateVersion());
            createArtifact.getFirstVersion().setContent(new VersionContent());
            createArtifact.getFirstVersion().getContent().setContent(IoUtil.toString(content));
            createArtifact.getFirstVersion().getContent().setContentType("application/json");

            final io.apicurio.registry.rest.client.models.VersionMetaData metaData = registryClient.groups()
                    .byGroupId("default").artifacts().post(createArtifact, config -> {
                        config.queryParameters.ifExists = IfArtifactExists.FIND_OR_CREATE_VERSION;
                    }).getVersion();

            assert metaData != null;
            LOGGER.info("=====> Successfully created JSON Schema artifact in Service Registry: {}", metaData);
            LOGGER.info("---------------------------------------------------------");
        } catch (Exception t) {
            throw t;
        }
    }

    /**
     * Get the artifact from the registry.
     *
     * @param artifactId
     */
    public static ArtifactMetaData getSchemaFromRegistry(RegistryClient service, String artifactId) {

        LOGGER.info("---------------------------------------------------------");
        LOGGER.info("=====> Fetching artifact from the registry for JSON Schema with ID: {}", artifactId);
        try {
            final ArtifactMetaData metaData = service.groups().byGroupId("default").artifacts()
                    .byArtifactId(artifactId).get();
            assert metaData != null;
            LOGGER.info("=====> Successfully fetched JSON Schema artifact in Service Registry: {}", metaData);
            LOGGER.info("---------------------------------------------------------");
            return metaData;
        } catch (Exception t) {
            throw t;
        }
    }
}

package main

import (
	"context"
	"flag"
	"fmt"
	// 3.0.6:
	registry3 "github.com/apicurio/apicurio-registry/go-sdk/pkg/registryclient-v3"
	"github.com/apicurio/apicurio-registry/go-sdk/pkg/registryclient-v3/models"
	// 3.0.7 and later:
	// registry3 "github.com/apicurio/apicurio-registry/go-sdk/v3/pkg/registryclient-v3"
	// "github.com/apicurio/apicurio-registry/go-sdk/v3/pkg/registryclient-v3/models"
	kiotaAuth "github.com/microsoft/kiota-abstractions-go/authentication"
	kiotaHttp "github.com/microsoft/kiota-http-go"
	"regexp"
)

func initClient(registryUrl *string) *registry3.ApiClient {
	prefix, err := regexp.Compile("^https?://.*")
	if err != nil {
		panic("Unexpected error: " + err.Error())
	}
	if !prefix.MatchString(*registryUrl) {
		s := "http://" + *registryUrl
		registryUrl = &s
	}
	suffix, err := regexp.Compile(".*/apis/registry/v3/?")
	if err != nil {
		panic("Unexpected error: " + err.Error())
	}
	if !suffix.MatchString(*registryUrl) {
		s := *registryUrl + "/apis/registry/v3"
		registryUrl = &s
	}

	// Using the default adapter: kiota-http-go's default client-side middleware chain includes
	// a CompressionHandler, which gzip-compresses outgoing request bodies (Content-Encoding: gzip).
	// This has no effect on how the server compresses its responses.
	adapter, err := kiotaHttp.NewNetHttpRequestAdapter(
		&kiotaAuth.AnonymousAuthenticationProvider{},
	)
	if err != nil {
		panic("Unexpected error: " + err.Error())
	}
	adapter.SetBaseUrl(*registryUrl)

	return registry3.NewApiClient(adapter)
}

func getServerInfo(client *registry3.ApiClient) {
	res, err := client.System().Info().Get(context.Background(), nil)
	if res != nil {
		fmt.Printf("Server name: %s\n", *res.GetName())
		fmt.Printf("Server version: %s\n", *res.GetVersion())
	} else {
		handleError(err)
	}
}

func createNewArtifactVersion(client *registry3.ApiClient) {
	newContent := models.NewVersionContent()
	content := `{"openapi": "3.0.0", "info": {"title": "My API", "version": "1.0.0"}, "paths": {}}`
	newContent.SetContent(&content)
	contentType := "application/json"
	newContent.SetContentType(&contentType)

	newVersion := models.NewCreateVersion()
	newVersion.SetContent(newContent)

	newArtifact := models.NewCreateArtifact()
	newArtifact.SetFirstVersion(newVersion)

	res, err := client.Groups().ByGroupId("default").Artifacts().Post(context.Background(), newArtifact, nil)
	if res != nil {
		fmt.Printf("Created version %s of artifact %s\n", *res.GetVersion().GetVersion(), *res.GetVersion().GetArtifactId())
	} else {
		handleError(err)
	}
}

func handleError(err error) {
	if err == nil {
		panic("No error value")
	}
	if details, ok := err.(*models.ProblemDetails); ok {
		fmt.Printf("Server error: %s\n", *details.GetDetail())
	} else {
		fmt.Printf("Unknown error: %s\n", err.Error())
	}
}

func main() {
	registryUrl := flag.String("url", "http://localhost:8080", "URL of the Apicurio Registry 3 server")
	flag.Parse()
	client := initClient(registryUrl)
	getServerInfo(client)
	createNewArtifactVersion(client)
}

